  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_article_spu` (`article_id`,`spu_id`),
  KEY `idx_article` (`article_id`),
  KEY `idx_spu` (`spu_id`)
) ENGINE=InnoDB AUTO_INCREMENT=47 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='文章-商品关联表';


-- ----------------------------
-- Table: mall-ease.content_banner
-- ----------------------------

CREATE TABLE `content_banner` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Banner名称（后台管理标识）',
  `pic` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '图片URL',
  `type` int DEFAULT NULL COMMENT '跳转类型：0-无跳转 1-活动页 2-商品详情(SPU) 3-专题页 4-外链 5-优选专区',
  `target_id` bigint DEFAULT NULL COMMENT '跳转目标ID（type=1/2/3/5时使用）',
  `url` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '跳转链接（type=4外链时使用）',
  `position` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '投放位置：home-首页',
  `sort` int DEFAULT NULL COMMENT '排序值',
  `status` tinyint(1) DEFAULT NULL COMMENT '状态：0-禁用 1-启用',
  `start_time` datetime DEFAULT NULL COMMENT '生效开始时间',
  `end_time` datetime DEFAULT NULL COMMENT '生效结束时间',
  `click_count` int DEFAULT NULL COMMENT '点击次数统计',
  `note` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `deleted` tinyint(1) DEFAULT NULL COMMENT '删除标记：0-未删除 1-已删除',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `creator` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `updater` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


