  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '删除标记：0-未删除 1-已删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_member_date` (`member_id`,`sign_date`),
  UNIQUE KEY `uk_reward_biz_key` (`reward_biz_key`),
