-- ----------------------------
-- Table: mall-ease.outbox_message
-- ----------------------------

CREATE TABLE `outbox_message` (
  `id` bigint NOT NULL COMMENT '消息ID',
  `topic` varchar(128) NOT NULL COMMENT '消息主题，如 stock.lock',
  `business_key` varchar(128) NOT NULL COMMENT '业务唯一键，如订单号',
  `payload` json NOT NULL COMMENT '消息体 JSON',
  `status` tinyint NOT NULL COMMENT '状态：0-PENDING，1-SENDING，2-SENT，3-DEAD',
  `retry_count` int NOT NULL DEFAULT '0' COMMENT '当前重试次数',
  `max_retry` int NOT NULL DEFAULT '3' COMMENT '最大重试次数',
  `next_retry_at` datetime NOT NULL COMMENT '下次允许投递时间',
  `last_error` varchar(512) DEFAULT NULL COMMENT '最近一次错误信息',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_topic_bizkey` (`topic`,`business_key`),
  KEY `idx_status_next_retry` (`status`,`next_retry_at`),
  KEY `idx_status_update_time` (`status`,`update_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Outbox 发件箱消息表';

