-- ----------------------------
-- Table: mall-ease.product_category
-- ----------------------------

CREATE TABLE `product_category` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `parent_id` bigint NOT NULL DEFAULT '0' COMMENT '父分类ID，0表示顶级分类',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '分类名称',
  `path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '层级路径，格式如 /1/7/8/，用于高效查询子树',
  `level` tinyint NOT NULL DEFAULT '0' COMMENT '层级深度：0=一级，1=二级，2=三级',
  `enable_status` tinyint NOT NULL DEFAULT '1' COMMENT '分类启用状态：0-禁用，1-启用',
  `is_nav` tinyint DEFAULT '0' COMMENT '是否导航栏显示：0-否 1-是',
  `sort` int DEFAULT '0' COMMENT '排序值，越小越靠前',
  `icon` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '分类图标',
  `image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '分类大图URL（用于专题页、banner等）',
  `keywords` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'SEO关键词',
  `description` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '分类描述',
  `deleted` tinyint DEFAULT '0' COMMENT '删除标记：0-未删除 1-已删除',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_parent_id` (`parent_id`) USING BTREE,
  KEY `idx_path` (`path`) USING BTREE,
  KEY `idx_level` (`level`) USING BTREE,
  KEY `idx_status_deleted` (`enable_status`,`deleted`) USING BTREE,
  KEY `idx_is_nav` (`is_nav`,`enable_status`,`deleted`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=104 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='商品分类表';


