  KEY `idx_category_id` (`category_id`),
  KEY `idx_attr_id` (`attr_id`)
) ENGINE=InnoDB AUTO_INCREMENT=140 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='分类-属性关联表';


-- ----------------------------
-- Table: mall-ease.product_category_brand_relation
-- ----------------------------

CREATE TABLE `product_category_brand_relation` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `category_id` bigint NOT NULL COMMENT '分类ID',
  `brand_id` bigint NOT NULL COMMENT '品牌ID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_category_brand` (`category_id`,`brand_id`),
  KEY `idx_category_id` (`category_id`),
  KEY `idx_brand_id` (`brand_id`)
) ENGINE=InnoDB AUTO_INCREMENT=63 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='分类-品牌关联表';


-- ----------------------------
-- Table: mall-ease.product_sku
-- ----------------------------

CREATE TABLE `product_sku` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `spu_id` bigint NOT NULL COMMENT 'SPU ID（关联 pms_spu.id）',
  `sku_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'SKU编码（唯一）',
  `pic` varchar(255) COLLATE utf8mb4_general_ci NOT NULL COMMENT 'SKU图片URL',
  `base_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'SKU基础成交价',
  `compare_at_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'SKU参考价',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除: 0-未删除, 1-已删除',
  `enable_status` tinyint NOT NULL DEFAULT '1' COMMENT '启用状态: 0-禁用, 1-启用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新人',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_sku_code` (`sku_code`) USING BTREE COMMENT 'SKU编码唯一索引',
  KEY `idx_spu_id` (`spu_id`) USING BTREE,
  KEY `idx_deleted_enable` (`deleted`,`enable_status`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=158 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='SKU基础信息表';


-- ----------------------------
-- Table: mall-ease.product_sku_promotion
-- ----------------------------

CREATE TABLE `product_sku_promotion` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `sku_id` bigint NOT NULL COMMENT 'SKU ID（关联 pms_sku.id）',
  `promotion_type` tinyint NOT NULL DEFAULT '0' COMMENT '促销类型: 0-无促销, 1-促销价, 2-会员价, 3-阶梯价, 4-满减价, 5-限时购',
  `preview_status` tinyint NOT NULL DEFAULT '0' COMMENT '是否为预告商品: 0-否, 1-是',
  `promotion_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '促销价格',
  `promotion_start_time` datetime DEFAULT NULL COMMENT '促销开始时间',
  `promotion_end_time` datetime DEFAULT NULL COMMENT '促销结束时间',
  `promotion_per_limit` int NOT NULL DEFAULT '0' COMMENT '活动限购数量（0表示不限购）',
  `gift_growth` int NOT NULL DEFAULT '0' COMMENT '赠送的成长值',
  `gift_point` int NOT NULL DEFAULT '0' COMMENT '赠送的积分',
  `use_point_limit` int DEFAULT NULL COMMENT '限制使用的积分数',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新人',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_sku_id` (`sku_id`) USING BTREE,
  KEY `idx_promotion_type` (`promotion_type`) USING BTREE,
  KEY `idx_promotion_time` (`promotion_start_time`,`promotion_end_time`) USING BTREE COMMENT '促销时间查询索引'
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='SKU促销信息表';

-- (0 rows)

-- ----------------------------
-- Table: mall-ease.product_sku_stock
-- ----------------------------

CREATE TABLE `product_sku_stock` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `sku_id` bigint NOT NULL COMMENT 'SKU ID（关联 pms_sku.id）',
  `spu_id` bigint DEFAULT NULL COMMENT 'SPU ID（冗余字段，便于按商品查询库存）',
  `stock` int NOT NULL DEFAULT '0' COMMENT '可用库存',
  `lock_stock` int NOT NULL DEFAULT '0' COMMENT '锁定库存（下单未支付）',
  `sale` int NOT NULL DEFAULT '0' COMMENT '累计销量',
  `low_stock` int NOT NULL DEFAULT '0' COMMENT '库存预警值',
  `stock_status` tinyint NOT NULL DEFAULT '1' COMMENT '库存状态: 0-无货, 1-有货, 2-预售',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新人',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_sku_id` (`sku_id`) USING BTREE COMMENT 'SKU ID唯一索引（一对一关系）',
  KEY `idx_stock_status` (`stock_status`) USING BTREE,
  KEY `idx_low_stock` (`stock`,`low_stock`) USING BTREE COMMENT '库存预警查询',
  KEY `idx_spu_id` (`spu_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=144 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='SKU库存表';


-- ----------------------------
-- Table: mall-ease.product_sku_stock_log
-- ----------------------------

CREATE TABLE `product_sku_stock_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `sku_id` bigint NOT NULL COMMENT 'SKU ID',
  `spu_id` bigint NOT NULL COMMENT 'SPU ID',
  `change_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '变更类型：UPDATE/BATCH_UPDATE/STATUS_UPDATE/ADJUST_IN/ADJUST_OUT/LOCK/\n  UNLOCK/CONFIRM',
  `before_stock` int NOT NULL DEFAULT '0' COMMENT '变更前可用库存',
  `after_stock` int NOT NULL DEFAULT '0' COMMENT '变更后可用库存',
  `before_lock_stock` int NOT NULL DEFAULT '0' COMMENT '变更前锁定库存',
  `after_lock_stock` int NOT NULL DEFAULT '0' COMMENT '变更后锁定库存',
  `change_quantity` int NOT NULL DEFAULT '0' COMMENT '变更数量',
  `source_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源类型：admin/order',
  `source_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源单号',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_sku_id` (`sku_id`),
  KEY `idx_spu_id` (`spu_id`),
  KEY `idx_change_type` (`change_type`),
  KEY `idx_source_type_source_no` (`source_type`,`source_no`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='SKU库存流水日志表';


-- ----------------------------
-- Table: mall-ease.product_spu
-- ----------------------------

CREATE TABLE `product_spu` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `spu_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'SPU编码（唯一）',
  `brand_id` bigint NOT NULL DEFAULT '0' COMMENT '品牌ID',
  `category_id` bigint NOT NULL DEFAULT '0' COMMENT '分类ID',
  `category_ids` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分类路径(逗号分隔): 1,5,32',
  `name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'SPU名称',
  `sub_title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '副标题',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT 'SPU描述',
  `keywords` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '关键字',
  `pic` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'SPU主图URL',
  `album_pics` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '画册图片（逗号分割）',
  `unit` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '单位',
  `weight` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '商品重量（克）',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除: 0-未删除, 1-已删除',
  `publish_status` tinyint NOT NULL DEFAULT '0' COMMENT '上架状态: 0-下架, 1-上架',
  `new_status` tinyint NOT NULL DEFAULT '0' COMMENT '新品状态: 0-不是新品, 1-新品',
  `recommend_status` tinyint NOT NULL DEFAULT '0' COMMENT '推荐状态: 0-不推荐, 1-推荐',
  `verify_status` tinyint NOT NULL DEFAULT '0' COMMENT '审核状态: 0-未审核, 1-审核通过',
  `sort` int NOT NULL DEFAULT '0' COMMENT '排序',
  `sale` int NOT NULL DEFAULT '0' COMMENT '总销量（所有 SKU 销量之和）',
  `min_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '最低价格（所有 SKU 最低价）',
  `max_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '最高价格（所有 SKU 最高价）',
  `in_stock` int NOT NULL DEFAULT '0' COMMENT '是否有货（任一 SKU 有库存即为 true）',
  `brand_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '品牌名称（冗余）',
  `category_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分类名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新人',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  `has_staged_changes` tinyint NOT NULL DEFAULT '0' COMMENT '是否存在未发布草稿',
  `published_version` int NOT NULL DEFAULT '0' COMMENT '当前已发布版本号',
  `published_at` datetime DEFAULT NULL COMMENT '最近发布时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_spu_code` (`spu_code`) USING BTREE COMMENT 'SPU编码唯一索引',
  KEY `idx_brand_id` (`brand_id`) USING BTREE,
  KEY `idx_category_id` (`category_id`) USING BTREE,
  KEY `idx_deleted_publish` (`deleted`,`publish_status`) USING BTREE COMMENT '商品列表查询索引',
  KEY `idx_verify_status` (`verify_status`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=29 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='SPU标准产品单元表';


-- ----------------------------
-- Table: mall-ease.product_spu_detail
-- ----------------------------

CREATE TABLE `product_spu_detail` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `spu_id` bigint NOT NULL COMMENT 'SPU ID（关联 pms_spu.id）',
  `detail_title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '详情标题',
  `detail_desc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '详情描述',
  `detail_html` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '产品详情网页内容（PC端）',
  `detail_mobile_html` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '移动端网页详情',
  `service_ids` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '产品服务（逗号分割）: 1-无忧退货, 2-快速退款, 3-免费包邮',
  `packing_list` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '包装清单',
  `after_sale_service` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '售后服务',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新人',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_spu_id` (`spu_id`) USING BTREE COMMENT 'SPU ID唯一索引（一对一关系）'
) ENGINE=InnoDB AUTO_INCREMENT=29 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='SPU详情表';


-- ----------------------------
-- Table: mall-ease.product_spu_publish_record
-- ----------------------------

CREATE TABLE `product_spu_publish_record` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `spu_id` bigint NOT NULL COMMENT '商品ID',
  `spu_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '商品名称（冗余）',
  `operator_id` bigint DEFAULT NULL COMMENT '操作人ID',
  `operator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '操作人姓名',
  `action` tinyint NOT NULL COMMENT '操作类型: 1-上架, 0-下架',
  `from_status` tinyint DEFAULT NULL COMMENT '原状态 : 1-上架, 0-下架',
  `to_status` tinyint NOT NULL COMMENT '新状态: 1-上架, 0-下架',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '操作原因',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_product_id` (`spu_id`) USING BTREE,
  KEY `idx_operator_id` (`operator_id`) USING BTREE,
  KEY `idx_create_time` (`create_time`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=121 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='商品上下架记录表';


-- ----------------------------
-- Table: mall-ease.product_spu_snapshot
-- ----------------------------

CREATE TABLE `product_spu_snapshot` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `spu_id` bigint NOT NULL COMMENT 'SPU ID',
  `version` int NOT NULL DEFAULT '1' COMMENT '已发布版本号',
  `publish_status` tinyint NOT NULL DEFAULT '1' COMMENT '发布状态：0-下架 1-上架',
  `name` varchar(200) COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品名称',
  `sub_title` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '副标题',
  `pic` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '主图',
  `min_price` decimal(10,2) DEFAULT NULL COMMENT '最低价',
  `max_price` decimal(10,2) DEFAULT NULL COMMENT '最高价',
  `brand_id` bigint DEFAULT NULL COMMENT '品牌ID',
  `brand_name` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '品牌名称',
  `category_id` bigint DEFAULT NULL COMMENT '分类ID',
  `category_name` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '分类名称',
  `category_ids` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '分类路径',
  `snapshot_json` longtext COLLATE utf8mb4_general_ci NOT NULL COMMENT '已发布快照JSON',
  `snapshot_hash` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '快照摘要，便于判断是否有变化',
  `published_at` datetime NOT NULL COMMENT '发布时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_spu_id` (`spu_id`),
  KEY `idx_publish_status` (`publish_status`),
  KEY `idx_category_id` (`category_id`),
  KEY `idx_brand_id` (`brand_id`),
  KEY `idx_published_at` (`published_at`)
) ENGINE=InnoDB AUTO_INCREMENT=77 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='商品已发布快照表';


-- ----------------------------
-- Table: mall-ease.product_stock_reservation
-- ----------------------------

CREATE TABLE `product_stock_reservation` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `order_no` varchar(32) NOT NULL COMMENT '订单编号（幂等键）',
  `sku_id` bigint NOT NULL COMMENT 'SKU ID',
  `quantity` int NOT NULL COMMENT '预占数量',
  `reservation_status` tinyint NOT NULL COMMENT '库存预占状态：1-LOCKED，2-RELEASED，3-CONFIRMED',
  `expire_time` datetime NOT NULL COMMENT '过期时间（创建时间+30分钟）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_order_sku` (`order_no`,`sku_id`) COMMENT '幂等核心：同一订单同一SKU只能有一条预占记录',
  KEY `idx_status_expire` (`reservation_status`,`expire_time`) COMMENT '到期扫描：查找已过期的锁定记录',
  KEY `idx_order_no` (`order_no`) COMMENT '按订单查询：解锁/确认时使用',
  KEY `idx_status_release` (`reservation_status`) USING BTREE COMMENT '库存解锁状态修改： 解锁/确认时使用'
) ENGINE=InnoDB AUTO_INCREMENT=5293 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='库存预占明细表';


-- ----------------------------
-- Table: mall-ease.trade_cart_item
-- ----------------------------

CREATE TABLE `trade_cart_item` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint unsigned NOT NULL COMMENT '用户ID',
  `sku_id` bigint unsigned NOT NULL COMMENT 'SKU ID',
  `spu_id` bigint unsigned NOT NULL COMMENT 'SPU ID',
  `quantity` int unsigned NOT NULL DEFAULT '1' COMMENT '商品数量',
  `checked` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '选中状态',
  `spu_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商品名称',
  `sku_pic` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'SKU图片',
  `sku_attrs` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'SKU规格属性',
  `price` decimal(10,2) NOT NULL COMMENT '加入时单价',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_sku` (`user_id`,`sku_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_spu_id` (`spu_id`)
) ENGINE=InnoDB AUTO_INCREMENT=5042 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='购物车明细表';


-- ----------------------------
-- Table: mall-ease.trade_order
-- ----------------------------

CREATE TABLE `trade_order` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `order_no` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '订单编号',
  `request_id` varchar(64) COLLATE utf8mb4_general_ci NOT NULL COMMENT '幂等请求ID（防重复提交）',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `receiver_name` varchar(64) COLLATE utf8mb4_general_ci NOT NULL COMMENT '收货人姓名',
  `receiver_phone` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '收货人电话',
  `receiver_province` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '省',
  `receiver_city` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '市',
  `receiver_district` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '区',
  `receiver_address` varchar(256) COLLATE utf8mb4_general_ci NOT NULL COMMENT '详细地址',
  `total_amount` decimal(10,2) NOT NULL COMMENT '商品总金额',
  `freight_amount` decimal(10,2) DEFAULT '0.00' COMMENT '运费',
  `discount_amount` decimal(10,2) DEFAULT '0.00' COMMENT '优惠金额',
  `pay_amount` decimal(10,2) NOT NULL COMMENT '应付金额',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '订单状态: 1-待发货 2-待收货 3-已完成 4-已取消 5-待支付 6-已支付 7-处理中 8-处理失败',
  `pay_expire_time` datetime DEFAULT NULL COMMENT '订单支付截止时间',
  `payment_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT ' 支付单号',
  `pay_channel` tinyint(1) DEFAULT NULL COMMENT '支付渠道: 1-支付宝, 2-微信, 9-模拟',
  `paid_time` datetime DEFAULT NULL COMMENT '支付成功时间',
  `order_source` tinyint NOT NULL DEFAULT '0' COMMENT '订单来源：0-普通，1-秒杀',
  `flash_session_id` bigint DEFAULT NULL COMMENT '秒杀场次ID（秒杀订单专用）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `stock_process_status` tinyint NOT NULL COMMENT '0：未开始\n1：锁库中\n2：已锁定\n3：锁库结果未知\n4：锁库失败\n5：确认扣减中\n6：已确认扣减\n7：确认扣减失败\n8：释放中\n9：已释放\n10：释放失败',
  `flash_product_id` bigint DEFAULT NULL COMMENT '秒杀商品ID（flash_product表，秒杀订单专用）',
  `remark` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '订单备注',
  PRIMARY KEY (`id`),
  UNIQUE KEY `order_no` (`order_no`),
  UNIQUE KEY `request_id` (`request_id`),
  UNIQUE KEY `idx_order_no` (`order_no`) USING BTREE,
  KEY `idx_user_id` (`user_id`),
  KEY `idx_request_id` (`request_id`),
  KEY `idx_status` (`status`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=1786 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='订单主表';


-- ----------------------------
-- Table: mall-ease.trade_order_item
-- ----------------------------

CREATE TABLE `trade_order_item` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `order_id` bigint NOT NULL COMMENT '订单ID',
  `order_no` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '订单编号',
  `spu_id` bigint NOT NULL COMMENT 'SPU ID',
  `sku_id` bigint NOT NULL COMMENT 'SKU ID',
  `spu_name` varchar(256) COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品名称',
  `sku_pic` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'SKU图片',
  `sku_attrs` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'SKU规格属性',
  `price` decimal(10,2) NOT NULL COMMENT '下单时单价',
  `quantity` int NOT NULL COMMENT '购买数量',
  `subtotal` decimal(10,2) NOT NULL COMMENT '小计金额',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_order_id` (`order_id`),
  KEY `idx_sku_id` (`sku_id`)
) ENGINE=InnoDB AUTO_INCREMENT=5344 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='订单商品表';


-- ----------------------------
-- Table: mall-ease.trade_order_operation_log
-- ----------------------------

CREATE TABLE `trade_order_operation_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `order_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '订单编号',
  `operator_id` bigint NOT NULL COMMENT '操作人ID',
  `operator_name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '操作人名称',
  `operation_type` tinyint NOT NULL COMMENT '操作类型：1-发货 2-强制取消 3-修改地址 4-修改备注 5-调整金额 6-退款',
  `detail` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作详情',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_order_no` (`order_no`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='订单操作日志表';


-- ----------------------------
-- Table: mall-ease.trade_order_shipment
-- ----------------------------

CREATE TABLE `trade_order_shipment` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `order_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '订单编号',
  `logistics_company` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '物流公司名称',
  `logistics_code` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '物流公司编码（快递100编码）',
  `logistics_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '物流运单号',
  `shipper_name` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '发货人',
  `ship_time` datetime NOT NULL COMMENT '发货时间',
  `receive_time` datetime DEFAULT NULL COMMENT '签收时间',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '物流状态：0-已发货 1-运输中 2-已签收',
  `logistics_info` json DEFAULT NULL COMMENT '物流轨迹JSON（快递100回调更新）',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_order_no` (`order_no`),
  KEY `idx_logistics_no` (`logistics_no`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='订单物流发货表';


-- ----------------------------
-- Table: mall-ease.trade_payment_notify_log
-- ----------------------------

CREATE TABLE `trade_payment_notify_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `channel` tinyint NOT NULL COMMENT '支付渠道: 1-支付宝, 2-微信, 9-模拟',
  `notify_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '渠道回调唯一ID',
  `payment_no` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '支付单号',
  `order_no` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '订单号',
  `third_trade_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '第三方交易号',
  `sign_verified` tinyint NOT NULL DEFAULT '0' COMMENT '签名校验: 0-未通过, 1-通过',
  `process_status` tinyint NOT NULL DEFAULT '1' COMMENT '处理状态: 1-待处理, 2-处理成功, 3-重复忽略, 4-处理失败',
  `error_msg` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '错误信息',
  `raw_body` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '回调原文',
  `notify_time` datetime DEFAULT NULL COMMENT '回调触发时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_channel_notify` (`channel`,`notify_id`),
  KEY `idx_payment_no` (`payment_no`),
  KEY `idx_order_no` (`order_no`),
  KEY `idx_notify_time` (`notify_time`),
  KEY `idx_third_trade_no` (`third_trade_no`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='支付回调日志表';


-- ----------------------------
-- Table: mall-ease.trade_payment_order
-- ----------------------------

CREATE TABLE `trade_payment_order` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `payment_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `pay_amount` decimal(10,2) NOT NULL COMMENT '支付金额',
  `pay_channel` tinyint DEFAULT NULL COMMENT '支付渠道: 1-支付宝, 2-微信, 9-模拟',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '支付状态: 1-待支付, 2-支付成功, 3-已关闭, 4-支付失败',
  `third_trade_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `third_buyer_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `expire_time` datetime NOT NULL COMMENT '支付过期时间',
  `paid_time` datetime DEFAULT NULL COMMENT '支付成功时间',
  `notify_time` datetime DEFAULT NULL COMMENT '最新回调时间',
  `notify_count` int NOT NULL DEFAULT '0' COMMENT '回调次数',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_payment_no` (`payment_no`),
  KEY `idx_status_expire` (`status`,`expire_time`),
  KEY `idx_user_create` (`user_id`,`create_time`),
  KEY `idx_third_trade_no` (`third_trade_no`),
  KEY `uk_order_no` (`order_no`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=825 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='交易支付单表';


-- ----------------------------
-- Table: mall-ease.user_admin
-- ----------------------------

CREATE TABLE `user_admin` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `username` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `password` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `icon` varchar(500) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '头像',
  `email` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '邮箱',
  `nick_name` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '昵称',
  `note` varchar(500) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '备注信息',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `login_time` datetime DEFAULT NULL COMMENT '最后登录时间',
  `status` int DEFAULT '1' COMMENT '帐号启用状态：0->禁用；1->启用',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC COMMENT='后台用户表';


-- ----------------------------
-- Table: mall-ease.user_admin_role_relation
-- ----------------------------

CREATE TABLE `user_admin_role_relation` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `admin_id` bigint DEFAULT NULL,
  `role_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=41 DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC COMMENT='后台用户和角色关系表';


-- ----------------------------
-- Table: mall-ease.user_member
-- ----------------------------

CREATE TABLE `user_member` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `member_level_id` bigint DEFAULT NULL COMMENT '会员等级ID',
  `username` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用户名',
  `password` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '密码',
  `nick_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '昵称',
  `phone` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '手机号码',
  `email` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '邮箱',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态：0-禁用 1-启用',
  `icon` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '头像URL',
  `gender` tinyint DEFAULT '0' COMMENT '性别：0-未知 1-男 2-女',
  `birthday` date DEFAULT NULL COMMENT '生日',
  `city` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '所在城市',
  `job` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '职业',
  `personalized_signature` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '个性签名',
  `source_type` tinyint DEFAULT '0' COMMENT '来源：0-其他 1-PC 2-H5 3-Android 4-IOS 5-小程序',
  `integration` int NOT NULL DEFAULT '0' COMMENT '积分',
  `growth` int NOT NULL DEFAULT '0' COMMENT '成长值',
  `lucky_count` int NOT NULL DEFAULT '0',
  `history_integration` int NOT NULL DEFAULT '0' COMMENT '历史积分数量',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '删除标记：0-未删除 1-已删除',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `login_time` datetime DEFAULT NULL COMMENT '最后登录时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_username` (`username`),
  UNIQUE KEY `uk_phone` (`phone`),
  KEY `idx_member_level_id` (`member_level_id`),
  KEY `idx_status` (`status`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='会员表';


-- ----------------------------
-- Table: mall-ease.user_member_address
-- ----------------------------

CREATE TABLE `user_member_address` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `member_id` bigint NOT NULL COMMENT '会员ID',
  `receiver_name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '收货人姓名',
  `receiver_phone` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '收货人电话',
  `province` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '省份',
  `city` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '城市',
  `district` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '区县',
  `detail_address` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '详细地址',
  `is_default` tinyint NOT NULL DEFAULT '0' COMMENT '是否默认：0-否 1-是',
  `label` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '地址标签（家、公司、学校等）',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0-正常 1-已删除',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_member_id` (`member_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='会员收货地址表';


-- ----------------------------
-- Table: mall-ease.user_member_level
-- ----------------------------

CREATE TABLE `user_member_level` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '等级名称',
  `growth_point` int NOT NULL DEFAULT '0' COMMENT '成长点门槛',
  `default_status` tinyint NOT NULL DEFAULT '0' COMMENT '是否默认等级：0-否 1-是',
  `free_freight_point` decimal(10,2) DEFAULT NULL COMMENT '免运费标准（订单金额）',
  `comment_growth_point` int NOT NULL DEFAULT '0' COMMENT '评价获取成长值',
  `privilege_free_freight` tinyint NOT NULL DEFAULT '0' COMMENT '免邮特权：0-否 1-是',
  `privilege_sign_in` tinyint NOT NULL DEFAULT '0' COMMENT '签到特权：0-否 1-是',
  `privilege_comment` tinyint NOT NULL DEFAULT '0' COMMENT '评论获奖励 特权：0-否 1-是',
  `privilege_promotion` tinyint NOT NULL DEFAULT '0' COMMENT '专享活动 特权：0-否 1-是',
  `privilege_member_price` tinyint NOT NULL DEFAULT '0' COMMENT '会员价格特权：0-否 1-是',
  `privilege_birthday` tinyint NOT NULL DEFAULT '0' COMMENT '生日特权：0-否 1-是',
  `note` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_growth_point` (`growth_point`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='会员等级表';


-- ----------------------------
-- Table: mall-ease.user_member_reward_log
-- ----------------------------

CREATE TABLE `user_member_reward_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `member_id` bigint NOT NULL COMMENT '会员ID',
  `business_type` varchar(32) NOT NULL COMMENT '业务类型',
  `business_key` varchar(80) NOT NULL COMMENT '业务幂等键',
  `integration_delta` int NOT NULL DEFAULT '0' COMMENT '积分变更量',
  `growth_delta` int NOT NULL DEFAULT '0' COMMENT '成长值变更量',
  `reason` varchar(255) DEFAULT NULL COMMENT '变更原因',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_biz` (`business_type`,`business_key`),
  KEY `idx_member_time` (`member_id`,`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='会员奖励流水';


-- ----------------------------
-- Table: mall-ease.user_menu
-- ----------------------------

CREATE TABLE `user_menu` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `parent_id` bigint DEFAULT NULL COMMENT '父级ID',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `title` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '菜单名称',
  `level` int DEFAULT NULL COMMENT '菜单级数',
  `sort` int DEFAULT NULL COMMENT '菜单排序',
  `name` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '前端名称',
  `icon` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '前端图标',
  `hidden` int DEFAULT NULL COMMENT '前端隐藏',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC COMMENT='后台菜单表';


-- ----------------------------
-- Table: mall-ease.user_resource
-- ----------------------------

CREATE TABLE `user_resource` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `name` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '资源名称',
  `url` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '资源URL',
  `description` varchar(500) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '描述',
  `category_id` bigint DEFAULT NULL COMMENT '资源分类ID',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=24 DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC COMMENT='后台资源表';


-- ----------------------------
-- Table: mall-ease.user_role
-- ----------------------------

CREATE TABLE `user_role` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '名称',
  `role_code` varchar(64) NOT NULL COMMENT '角色稳定编码，供程序判断使用',
  `description` varchar(500) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '描述',
  `admin_count` int DEFAULT NULL COMMENT '后台用户数量',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后修改时间',
  `status` int DEFAULT '1' COMMENT '启用状态：0->禁用；1->启用',
  `sort` int DEFAULT '0',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_user_role_role_code` (`role_code`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC COMMENT='后台用户角色表';


-- ----------------------------
-- Table: mall-ease.user_role_menu_relation
-- ----------------------------

CREATE TABLE `user_role_menu_relation` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `role_id` bigint DEFAULT NULL COMMENT '角色ID',
  `menu_id` bigint DEFAULT NULL COMMENT '菜单ID',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=229 DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC COMMENT='后台角色菜单关系表';


-- ----------------------------
-- Table: mall-ease.user_role_resource_relation
-- ----------------------------

CREATE TABLE `user_role_resource_relation` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `role_id` bigint DEFAULT NULL COMMENT '角色ID',
  `resource_id` bigint DEFAULT NULL COMMENT '资源ID',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=403 DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC COMMENT='后台角色资源关系表';


SET FOREIGN_KEY_CHECKS=1;
